class Countdown:
    def __init__(self, start):
        self.remaining = start
    def __iter__(self):
        return self
    def __next__(self):
        if self.remaining <= 0:
            raise StopIteration
        value = self.remaining
        self.remaining -= 1
        return value

counter = Countdown(2)
print(iter(counter) is counter)
print(next(counter))
print(list(Countdown(2)))
print(list(counter))
